head.script:
// 20250207 반영 ELW시장팀+ETN시장팀 = 구조화증권시장팀(2B40), 당번그룹코드(14), ETN,ELW법인제출(15), 업무마감(3D)
// 20250509 ETF, PF 법인제출(18) 생성 및 PF(상장형 수익증권) 체크로직 추가
// 업무마감관리
scwin.gNowDate;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
// 당번그룹구분 코드 = 유가 공시팀(11), 유가 시장팀(12), 유가 ETF시장팀(13),
// 유가 ETN시장팀(14) = 구조화증권 시장팀 , 유가 ELW시장팀(15) 사용안함  20250207,
// 코스닥 공시팀 : 21, 코스닥 시장팀 : 22, 예방감시팀(유가) : 32, 예방감시팀(코스닥) : 31, 복합시장감시팀(ELW) : 33, 예방감시팀(코넥스) : 34, 예방감시팀(배출권) : 35, 채권 상장팀 : 41, 코넥스 공시팀 : 61, 코넥스 시장팀 : 62
scwin.gDudyTp;
scwin.gDutyChrg = js_duty_chrg; // 세션정보
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03
scwin.gSecuGrpID;
scwin.gStep1;
scwin.gStep2;
scwin.gStep3;
scwin.gStep4;
scwin.gStatSelf;
scwin.gStep2Tm;
scwin.gStep3Tm;
scwin.gStep4Tm;
scwin.gStatSelfTm;
scwin.gReopenTp; // 법인제출 재개시구분: 22=제출 만 재개시, 23= 제출 및 업무 재개시,  24:제출 만 재개시

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.allHidden();
        scwin.setCode();
        await scwin.initSearch();

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_CloseProcs",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_CloseProcs=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF45000.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_CloseProcs_OnSuccess
 * @description Close Procs On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_CloseProcs_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001", ""));
        scwin.allHidden();
        await scwin.initSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF45000.trs_CloseProcs_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_CloseProcs_OnFail
 * @description Close Procs On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_CloseProcs_OnFail = async function() {
    try {
        await $c.win.alert('trs_CloseProcs.OnFail() :' + trs_CloseProcs.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF45000.trs_CloseProcs_OnFail" });
    }
};

/**
 * @method
 * @name img_submit_reopen2_onclick
 * @description 「법인제출재개시」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_submit_reopen2_onclick = async function() {
    try {
        txb_procs_stat.setValue("img_submit_reopen2");
        await scwin.closeProcess(22); // 업무마감전 제출재개시
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF45000.img_submit_reopen2_onclick" });
    }
};

/**
 * @method
 * @name img_submit_close2_onclick
 * @description 「법인제출마감」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_submit_close2_onclick = async function() {
    try {
        txb_procs_stat.setValue("img_submit_close2");
        await scwin.closeProcess(1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF45000.img_submit_close2_onclick" });
    }
};

/**
 * @method
 * @name img_biz_close2_onclick
 * @description 「업무마감」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_biz_close2_onclick = async function() {
    try {
        txb_procs_stat.setValue("img_biz_close2");
        if (scwin.gDudyTp === '13') {
            // ETF시장팀 체크 LSH_20160912
            await scwin.etfCloseCheck();
        } else if (scwin.gDudyTp === '14') {
            // ETN시장팀 체크 LSH_20160912
            await scwin.etnCloseCheck();
        }
        // ELW시장팀 체크_20230127

        // ELW시장팀+ETN시장팀 통합 20250207

        /*else if(gDudyTp == '15') {
    		fn_elwCloseCheck();
    	} */
        else if (scwin.gDudyTp === '22' || scwin.gDudyTp === '11') {
            // 코스닥 시장운영팀/유가 공시팀 체크 공시일정표에 미확정 목록이 있을시 마감을 못하게 한다.
            await scwin.mktOperTeamCloseCheck();
        } else if (scwin.gDudyTp === '32' || scwin.gDudyTp === '31' || scwin.gDudyTp === '34' || scwin.gDudyTp === '35' || scwin.gDudyTp === '33') {
            // 예방감시팀(유가,코스닥,코넥스,배출권)의 타시스템 공시가 제출 되지 않았으면 마감을 못하게 한다. LSH_20161017
            // ELW 업무가 사이버감시팀으로 넘어오면서 기존에 없던 타시스템 공시 마감 기능 추가 KBoY_20220224
            await scwin.otherSystemDisclsCloseCheck();
        } else if (scwin.gDudyTp === '16') {
            // 디지털증권시장팀 체크_20230914
            await scwin.digitalCloseCheck();
        } else {
            // 1. 승인안된 공시가 있는지 체크
            await scwin.getCount();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF45000.img_biz_close2_onclick" });
    }
};

/**
         * @method
         * @name img_submit_reopen3_onclick
         * @description 「법인제출재개시」 클릭 이벤트
         * @returns {Promise<void>}
         * @hidden N
         */
scwin.img_submit_reopen3_onclick = async function() {
    try {
        txb_procs_stat.setValue("img_submit_reopen3");
        if (scwin.gReopenTp === '23') {
            await scwin.closeProcess(23); // 제출 및 업무 재개시

        } else {
            await scwin.closeProcess(24); // 제출만 재개시

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF45000.img_submit_reopen3_onclick" });
    }
};

