/**
 * @method
 * @name img_biz_close3_onclick
 * @description 「업무마감」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_biz_close3_onclick = async function() {
    try {
        txb_procs_stat.setValue("img_biz_close3");
        if (scwin.gDudyTp === '13') {
            // ETF시장팀 체크 LSH_20160912
            await scwin.etfCloseCheck();
        } else if (scwin.gDudyTp === '14') {
            // ETN시장팀 체크 LSH_20160912
            await scwin.etnCloseCheck();
        }
        // ELW시장팀 체크_20230127

        // ELW시장팀+ETN시장팀 통합 20250207

        /*else if(gDudyTp == '15') {
        	fn_elwCloseCheck();
        } */
        else if (scwin.gDudyTp === '22' || scwin.gDudyTp === '11') {
            // 코스닥 시장운영팀/유가 공시팀 체크 공시일정표에 미확정 목록이 있을시 마감을 못하게 한다.
            await scwin.mktOperTeamCloseCheck();
        } else if (scwin.gDudyTp === '21') {
            // 1. 코스닥 공시팀 체크 공시일정표에 미확인 목록이 있을 시 마감을 못하게 한다. ==> by LDJ_20121004
            // 2. 코스닥 공시팀 당번 미지정지 마감못하게 체크한다.
            // 3. 건전성 집중관리 화면 마감여부도 체크하도록 로직 추가함 by LDJ_20120830
            await scwin.mktOperTeamCloseCheckKosdaq();
        } else if (scwin.gDudyTp === '61') {
            // 코넥스 공시팀 추가 20130522 ldj
            // 1. 코넥스 공시팀 당번 미지정지 마감못하게 체크한다.
            // 2. 승인안된 공시가 있는지 체크한다.
            await scwin.dutyDesignCloseCheck(); // 당번지정여부 체크한다.

        } else if (scwin.gDudyTp === '32' || scwin.gDudyTp === '31' || scwin.gDudyTp === '34' || scwin.gDudyTp === '35') {
            // 예방감시팀(유가,코스닥,코넥스,배출권)의 타시스템 공시가 제출 되지 않았으면 마감을 못하게 한다. LSH_20161017
            await scwin.otherSystemDisclsCloseCheck();
        } else if (scwin.gDudyTp === '16') {
            // 디지털증권시장팀 체크_20230914
            await scwin.digitalCloseCheck();
        } else if (scwin.gDudyTp === '41') {
            // 채권상장팀 체크_20240510
            await scwin.bndCloseCheck();
        } else {
            // 1. 승인안된 공시가 있는지 체크
            await scwin.getCount();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF45000.img_biz_close3_onclick" });
    }
};

/**
         * @method
         * @name dts_CloseStatus_OnLoadCompleted
         * @description dts_CloseStatus 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
