         * @returns {void}
         * @hidden N
         */
scwin.dts_CloseStatus_OnLoadCompleted = function(rowcount) {
    try {
        // alert("로딩완료~");
        if (scwin.gDudyTp === '41') {
            // 채권상장팀일때...
            scwin.getBondMsg();
        } else {
            scwin.getMsg();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF45000.dts_CloseStatus_OnLoadCompleted" });
    }
};

