    // alert(gDudyTp);

};

/**
 * @method
 * @name getMsg
 * @description get Msg 처리
 * @returns {void}
 * @hidden N
 */
scwin.getMsg = function() {
    pnl_step_1.hide();
    pnl_step_2.hide();
    pnl_step_3.hide();
    pnl_step_4.hide();
    txb_cls_tm2_1.hide();
    scwin.gNowDate = dts_CloseStatus.getCellData(1, 'NOW');
    scwin.gStep1 = dts_CloseStatus.getCellData(1, 'STEP_1');
    scwin.gStep2 = dts_CloseStatus.getCellData(1, 'STEP_2');
    scwin.gStep3 = dts_CloseStatus.getCellData(1, 'STEP_3');
    scwin.gStep4 = dts_CloseStatus.getCellData(1, 'STEP_4');
    scwin.gStatSelf = dts_CloseStatus.getCellData(1, 'STAT_SELF');
    scwin.gStep2Tm = dts_CloseStatus.getCellData(1, 'STEP_2_TM');
    scwin.gStep3Tm = dts_CloseStatus.getCellData(1, 'STEP_3_TM');
    scwin.gStep4Tm = dts_CloseStatus.getCellData(1, 'STEP_4_TM');
    scwin.gStatSelfTm = dts_CloseStatus.getCellData(1, 'STEP_SELF_TM');
    txb_cls_tm2.setValue(" ■ 제출 마감시각 : " + scwin.gStep2Tm);
    txb_cls_tm3.setValue(" ■ 금감원 마감시각 : " + scwin.gStep3Tm);
    txb_cls_tmself.setValue(" ■ 업무 마감시각 : " + scwin.gStatSelfTm);
    txb_cls_tm4.setValue(" ■ 최종 마감시각 : " + scwin.gStep4Tm);

    // 현시각(시분)
    let vNowMMDD = scwin.gNowDate.substr(11, 2) + scwin.gNowDate.substr(14, 2);

    // alert(gStep1 + gStep2  + gStep3 + gStep4 );
    if ((scwin.gStep1 + scwin.gStep2 + scwin.gStep3 + scwin.gStep4) > 0) {
        txb_msg.setValue("");
        if (scwin.gStep1 === 1) {
            if (scwin.gStep4 === 2) {
                // 18:00 이전에 비정상적으로 최종업무 마감이 된 상태이면...
                img_step4.setBackgroundImage("../img/step_bg04_c.gif");
                pnl_step_4.show("");
                txb_now4.setValue("마감시각 : " + scwin.gStep4Tm);
                txa_step_4.setValue($c.stf.getMessageParam("MSG-0905", ""));
            } else {
                img_step1.setBackgroundImage("../img/step_bg01_c.gif");
                pnl_step_1.show("");
                txb_now1.setValue("현재시각 : " + scwin.gNowDate);
                txa_step_1.setValue($c.stf.getMessageParam("MSG-0901", ""));
            }
        }
        if (scwin.gStep2 === 1) {
            // 법인제출 마감 안 된상태

            img_step2.setBackgroundImage("../img/step_bg02_c.gif");
            pnl_step_2.show("");
            txb_now2.setValue("현재시각 : " + scwin.gNowDate);
            // setObjectValue(txa_step_2,  getMessageParam("MSG-0902", ""));
            txa_step_2.setValue($c.stf.getMessageParam("MSG-0906", ""));
            if (scwin.gDudyTp === "12" || scwin.gDudyTp === "22" || scwin.gDudyTp === "62" ||
                scwin.gDudyTp === "31" || scwin.gDudyTp === "32" || scwin.gDudyTp === "33" || scwin.gDudyTp === "34" || scwin.gDudyTp === "35") {
                // 유/코시장운영팀, 시장감시부 는 법인제출 마감 권한 없음.  코넥스 예방감시팀(34) 추가 by 20130625 예방감시(배출권)추가 20150306
                img_submit_reopen2.hide(); // 법인제출재개시 버튼
                img_submit_close2.hide(); // 법인제출마감 버튼

                if (scwin.gStatSelf === 1) {
                    // 해당부서 마감이 안되어있을경우
                    if (vNowMMDD >= "1600" &&
                        (scwin.gDudyTp === "31" || scwin.gDudyTp === "32" || scwin.gDudyTp === "33" || scwin.gDudyTp === "34" || scwin.gDudyTp === "35")) {
                        img_biz_close2.show(""); // 시장감시부 는  16시 이후 업무마감할 수 있다.

                    }
                } else {
                    img_biz_close2.hide();
                    txa_step_2.setValue($c.stf.getMessageParam("MSG-0913", ""));
                }
            } else {
                img_submit_reopen2.hide();
                img_submit_close2.show("");
                img_biz_close2.hide();
            }
        } else if (scwin.gStep2 === 2) {
            // 법인제출 마감된 상태

            img_step2.setBackgroundImage("../img/step_bg02_c.gif");
            pnl_step_2.show("");
            txb_now2.setValue("마감시각 : " + scwin.gStep2Tm);
            txa_step_2.setValue($c.stf.getMessageParam("MSG-0902", ""));
            if (scwin.gDudyTp === "12" || scwin.gDudyTp === "22" || scwin.gDudyTp === "62" ||
                scwin.gDudyTp === "31" || scwin.gDudyTp === "32" || scwin.gDudyTp === "33" || scwin.gDudyTp === "34" || scwin.gDudyTp === "35") {
                // 유/코시장운영팀, 시장감시부 는 법인제출 마감 권한 없음. *추가 20080829 유명현 상장심사2팀도 해당함.
                img_submit_reopen2.hide();
                img_submit_close2.hide();
                if (scwin.gStatSelf === 1) {
                    // 해당부서 마감이 안되어있을경우
                    if (vNowMMDD >= "1600" && (scwin.gDudyTp === "31" || scwin.gDudyTp === "32" || scwin.gDudyTp === "33" || scwin.gDudyTp === "34" || scwin.gDudyTp === "35")) {
                        img_biz_close2.show(""); // 시장감시부 는  16시 이후 업무마감할 수 있다.

                    }
                } else {
                    txa_step_2.setValue($c.stf.getMessageParam("MSG-0912", ""));
                    img_biz_close2.hide();
                }
            } else {
                // 법인제출 재개시할때 23시이전여부체크
                if (vNowMMDD < '2300') {
                    // 코스닥공시부 법인재출 재개시시 당번팀장, 부서장만 가능하도록 변경 SrM-000262928 20240419
                    if (scwin.gDudyTp === "21") {
                        if (scwin.gDutyChrg === 'Y' || scwin.gJobTitle === '40') {
                            img_submit_reopen2.show("");
                        } else {
                            img_submit_reopen2.hide();
                        }
                    } else {
                        img_submit_reopen2.show("");
                    }
                } else {
                    img_submit_reopen2.hide();
                }
                img_submit_close2.hide();
                if (scwin.gDudyTp === "13" || scwin.gDudyTp === "14" || scwin.gDudyTp === "16") {
                    // ETN시장팀(14), 신종증권(16)은 금감원과 관계없이 업무마감 버튼 생성, ELW시장팀(15) 삭제
                    // ETF시장팀(13) 추가 20250509
                    if (scwin.gStatSelf === 1) {
                        // 해당부서 마감이 안되어있을경우
                        img_biz_close2.show("");
                    } else {
                        txa_step_2.setValue($c.stf.getMessageParam("MSG-0912", ""));
                        img_biz_close2.hide();
                        img_submit_reopen2.hide();
                    }
                } else {
                    img_biz_close2.hide();
                }
            }
        } else {
            if (scwin.gStep3 !== 1 && scwin.gStep3 !== 2 && scwin.gStep4 !== 1) {
                // 시장감시부 는  16시 이후 업무마감할 수 있다. : 2009.02.09 수정 처리
                if (vNowMMDD >= "1600" && (scwin.gDudyTp === "31" || scwin.gDudyTp === "32" || scwin.gDudyTp === "33" || scwin.gDudyTp === "34" || scwin.gDudyTp === "35")) {
                    pnl_step_2.show("");
                    txb_now2.setValue("현재시각 : " + scwin.gNowDate);
                    img_submit_reopen2.hide();
                    img_submit_close2.hide();
                    img_biz_close2.hide();
                    if (scwin.gStatSelf === "1") {
                        // 해당부서 마감이 안되어있을경우
                        img_biz_close2.show("");
                    } else {
                        txa_step_2.setValue($c.stf.getMessageParam("MSG-0913", ""));
                        img_biz_close2.hide();
                    }
                }
            }
        }

        // 제출마감 된 상태 & 업무마감 안 된상태
        if (scwin.gStep3 === 1) {
            img_step3.setBackgroundImage("../img/step_bg03_c.gif");
            pnl_step_3.show("");
            txb_now3.setValue("현재시각 : " + scwin.gNowDate);
            txa_step_3.setValue($c.stf.getMessageParam("MSG-0903", ""));
            if (scwin.gDudyTp === "12" || scwin.gDudyTp === "22" || scwin.gDudyTp === "62" ||
                scwin.gDudyTp === "31" || scwin.gDudyTp === "32" || scwin.gDudyTp === "33" || scwin.gDudyTp === "34" || scwin.gDudyTp === "35") {
                // 유/코시장운영팀, 시장감시부 는 법인제출 마감 권한 없음.
                img_submit_reopen3.hide();
            } else {
                // 법인제출 재개시할때 23시이전여부체크
                if (vNowMMDD < '2300') {
                    scwin.gReopenTp = '24';
                    // 코스닥공시부 법인재출 재개시시 당번팀장, 부서장만 가능하도록 변경 SrM-000262928 2024712
                    if (scwin.gDudyTp === "21") {
                        if (scwin.gDutyChrg === 'Y' || scwin.gJobTitle === '40') {
                            img_submit_reopen3.show("");
                        } else {
                            img_submit_reopen3.hide();
                        }
                    } else {
                        img_submit_reopen3.show("");
                    }
                } else {
                    img_submit_reopen3.hide();
                }
            }
            if (scwin.gStatSelf === 1) {
                // 당번소속그룹 마감이 안되어있을경우
                img_biz_close3.show("");
            } else {
                img_biz_close3.hide();
            }
        } else if (scwin.gStep3 === 2) {
            // 당번소속그룹의 마감은 완료 & 최종마감이 안된 상태
            img_step3.setBackgroundImage("../img/step_bg03_c.gif");
            pnl_step_3.show("");
            txb_now3.setValue("현재시각 : " + scwin.gNowDate);
            txa_step_3.setValue($c.stf.getMessageParam("MSG-0904", ""));
            if (scwin.gDudyTp === "12" || scwin.gDudyTp === "22" || scwin.gDudyTp === "62" ||
                scwin.gDudyTp === "31" || scwin.gDudyTp === "32" || scwin.gDudyTp === "33" || scwin.gDudyTp === "34" || scwin.gDudyTp === "35") {
                // 유/코시장운영팀, 시장감시부 는 법인제출 마감 권한 없음.
                img_submit_reopen3.hide();
            } else {
                // 법인제출 재개시할때 23시이전여부체크
                if (vNowMMDD < '2300') {
                    scwin.gReopenTp = '23';
                    img_submit_reopen3.hide();
                } else {
                    img_submit_reopen3.hide();
                }
            }
            img_biz_close3.hide();
        }
        if (scwin.gStep4 === 1) {
            img_step4.setBackgroundImage("../img/step_bg04_c.gif");
            pnl_step_4.show("");
            txb_now4.setValue("마감시각 : " + scwin.gStep4Tm);
            txa_step_4.setValue($c.stf.getMessageParam("MSG-0905", ""));
        }
    } else {
        // alert("업무가 개시되지 않았습니다. ");
        txb_msg.setValue("알림 : 업무가 개시되지 않았습니다.");
    }

    // 당번그룹코드가 없는 사용자 로그인되면 처리버튼 모두 hidden 처리
    if (scwin.gDudyTp === "") {
        img_submit_close2.hide();
        img_submit_reopen2.hide();
        img_biz_close2.hide();
        img_submit_reopen3.hide();
        img_biz_close3.hide();
        txb_cls_tmself.hide();
        txb_cls_tm2_1.show("");
        txb_cls_tm2.setValue(" ■ (유) 제출 마감시각 : " + dts_CloseStatus.getCellData(1, 'STEP_11_TM'));
        txb_cls_tm2_1.setValue(" ■ (코) 제출 마감시각 : " + dts_CloseStatus.getCellData(1, 'STEP_12_TM'));
    }
};

/**
 * @method
 * @name initSearch
 * @description 화면 로딩시 디폴트 검색
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initSearch = async function() {
    await scwin.reload('N');
};

/**
 * @method
 * @name reload
 * @description reload 처리
 * @param {*} pReload pReload
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reload = async function(pReload) {
    await scwin.search(pReload);
    setTimeout("fn_Reload('Y')", 60000); // 1초 = 1000 , 60초 = 60000

};

/**
 * @method
 * @name closeProcess
 * @description 마감 및 재개시 처리 - 1 : 법인 제출 마감 - 3 :  업무 마감
 * @param {*} pCloseStep pCloseStep
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.closeProcess = async function(pCloseStep) {
    // alert(gLdMktTp +","+ js_duty);

    /**
     * 당번 공용아이디 제거하면서 마감은 팀전체가 할 수 있게 수정한다. (2011.06 P.H.J)
    if(js_jobtitl == '09' || js_jobtitl == '06') {	// 팀장이나 부서장일때

    	if( js_duty_chrg == 'N'  || js_duty_chrg == '') {
        //if(gLdMktTp == '9' && ( js_duty == 'N'  || js_duty == '')) {
        //if(gLdMktTp == '9' ) {
        //if(js_id !='001084' && js_id !='880912' && js_id !='010817' && js_id !='990540'  ) {    // 임시테스트용
    		alert("마감처리 권한이 없습니다.");
    		return;
    	}
    } else {
    	if( js_duty == 'N'  || js_duty == '') {
        //if(gLdMktTp == '9' && ( js_duty == 'N'  || js_duty == '')) {
        //if(gLdMktTp == '9' ) {
        //if(js_id !='001084' && js_id !='880912' && js_id !='010817' && js_id !='990540'  ) {    // 임시테스트용
    		alert("마감처리 권한이 없습니다.");
    		return;
    	}
    }
     */

    dts_CloseProcs.removeAll();
    dts_CloseProcs.insertRow();
    dts_CloseProcs.setCellData(1, "DUTY_GRP_TP", scwin.gDudyTp);
    dts_CloseProcs.setCellData(1, "LD_MKT_TP", scwin.gLdMktTp);
    dts_CloseProcs.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_CloseProcs.setCellData(1, "CLOSE_STEP", pCloseStep);
    let vProcMsg = "";
    if (pCloseStep === 1) {
        vProcMsg = "법인제출 마감";
    } else if (pCloseStep === 22 || pCloseStep === 23 || pCloseStep === 24) {
        vProcMsg = "법인제출 재개시";
    } else if (pCloseStep === 3) {
        vProcMsg = "업무 마감";
    }
    const vAnswer = confirm($c.stf.getMessageParam("MSG-A006", vProcMsg));
    if (vAnswer === true) {
        // 업무마감 처리에서 법인제출마감,법인제출재개시,업무마감 체크  LSH_20160411
        await scwin.businessClosingCheck();
    }
};

