        return false;
    }
};

/**
 * @method
 * @name dsclDutyDesignCheck
 * @description dscl Duty Design Check 처리
 * @param {String} flag flag
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dsclDutyDesignCheck = async function(flag) {
    if (flag === 'Y') {
        // 정상처리

        if (scwin.gDudyTp === '21') {
            // 코스닥 공시팀일 경우에만 실행되도록 수정 by LDJ_2013.03.05
            await scwin.cncntAdmCloseCheck(); // 해당 점검이 정상이라면 '건전성 집중관리' 마감여부 체크   -- by 2012.08.30 LDJ 추가

        } else if (scwin.gDudyTp === '11') {
            // 유가 공시팀 사후심사 체크(20151231)
            await scwin.affactProcsCheck();
        } else {
            await scwin.getCount(); // 다음 프로세스 진행

        }
    } else {
        await $c.win.alert("익일 공시 당번이 지정되지 않았습니다. 당번 지정 후 마감 해주세요.");
        return false;
    }
};

