/**
 * @method
 * @name businessClosingCheckResult
 * @description 업무마감 처리에서 법인제출마감,법인제출재개시,업무마감 체크  LSH_20160411
 * @param {*} pStat10 pStat10
 * @param {*} pStat30 pStat30
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.businessClosingCheckResult = async function(pStat10, pStat30) {
    const vProcsStat = txb_procs_stat.getValue();
    if (pStat30 === 0) {
        await $c.win.alert("이미 업무가 마감 되었습니다.");
        await scwin.reload('N');
    } else {
        // 법인제출재개시
        if (vProcsStat === 'img_submit_reopen2') {
            if (pStat10 === 0) {
                // 정상처리
                await scwin.closeProcessAction();
            } else {
                await $c.win.alert("이미 법인 제출이 재개시 되었습니다.");
                await scwin.reload('N');
            }

            // 법인제출마감

        } else if (vProcsStat === 'img_submit_close2') {
            if (pStat10 > 0) {
                // 정상처리
                await scwin.closeProcessAction();
            } else {
                await $c.win.alert("이미 법인 제출이 마감 되었습니다.");
                await scwin.reload('N');
            }

            // 업무마감

        } else if (vProcsStat === 'img_biz_close2') {
            if (pStat30 > 0) {
                // 정상처리
                await scwin.closeProcessAction();
            } else {
                await $c.win.alert("이미 업무가 마감 되었습니다.");
                await scwin.reload('N');
            }

            // 법인제출재개시

        } else if (vProcsStat === 'img_submit_reopen3') {
            if (pStat10 === 0) {
                // 정상처리
                await scwin.closeProcessAction();
            } else {
                await $c.win.alert("이미 법인 제출이 재개시 되었습니다.");
                await scwin.reload('N');
            }

            // 업무마감

        } else if (vProcsStat === 'img_biz_close3') {
            if (scwin.gDudyTp === "12" || scwin.gDudyTp === "22" || scwin.gDudyTp === "62" ||
                scwin.gDudyTp === "31" || scwin.gDudyTp === "32" || scwin.gDudyTp === "33" || scwin.gDudyTp === "34" || scwin.gDudyTp === "35") {
                if (pStat30 > 0) {
                    // 정상처리
                    await scwin.closeProcessAction();
                } else {
                    await $c.win.alert("이미 업무가 마감 되었습니다.");
                    await scwin.reload('N');
                }
            } else {
                if (pStat10 === 0 && pStat30 > 0) {
                    // 정상처리
                    await scwin.closeProcessAction();
                } else if (pStat10 > 0 && pStat30 > 0) {
                    await $c.win.alert("이미 법인 제출이 재개시 되었습니다.");
                    await scwin.reload('N');
                } else {
                    await $c.win.alert("이미 업무가 마감 되었습니다.");
                    await scwin.reload('N');
                }
            }
        }
    }
};

/**
 * @method
 * @name isuChrgNDesignCheckResult
 * @description 종목 담당자 미지정 체크(유가 공시팀, 코스닥 공시팀, 코넥스상장관리팀, ETF시장팀) LSH_20160912 상장형수익증권 종목담당자 지정 추가 20250509
 * @param {Number} cnt cnt
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isuChrgNDesignCheckResult = async function(cnt) {
    let menu_nm;
    if (scwin.gDudyTp === "11") {
        menu_nm = "공시업무별담당자지정(유)_STF30610";
    } else if (scwin.gDudyTp === "21") {
        menu_nm = "공시업무별담당자지정(코)_STF30611";
    } else if (scwin.gDudyTp === "61") {
        menu_nm = "공시업무별담당자지정(넥)_STF40080";
    } else if (scwin.gDudyTp === "13") {
        if (scwin.gSecuGrpID === "EF") {
            menu_nm = "ETF 종목 담당자 지정_STF30615";
        } else if (scwin.gSecuGrpID === "PF") {
            menu_nm = "상장형수익증권 종목담당자 지정_STF34200";
        }
    } else {
        menu_nm = "공시업무별담당자지정";
    }
    if (cnt === '0') {
        // 정상처리
        // 2017-07-12 KBoY (유)공시팀만 시장조치데이터 비교
        if (scwin.gDudyTp === "11") {
            await scwin.isClearMktActData();
        } else if (scwin.gDudyTp === "13") {
            if (scwin.gSecuGrpID === "EF") {
                // 상장형 수익증권 상장송수신 마감체크 20250509
                // EF체크로직을 끝내고 PF체크로직 시작
                await scwin.pfCloseCheck();
            } else if (scwin.gSecuGrpID === "PF") {
                // 투자유의 마감체크로직
                await scwin.isBzClsRelInvstwarnPF();
            }
        } else {
            // 업무마감
            await scwin.closeProcess(3);
        }
    } else {
        await $c.win.alert("익일 상장 종목의 담당자가 지정되지 않았습니다.\n" + menu_nm + " 화면의\n[미지정회사 담당자지정] 탭에서\n담당자 지정을 해주시기 바랍니다.");
        return false;
    }
};

